func ptrBookingCurve(p unsafe.Pointer, c int32) any {
	r := (*demandforecast.BookingCurve)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 4:
		return &r.Shares
	case 5:
		return &r.Loads
	case 6:
		return &r.FittedAt
	case 7:
		return &r.CreatedAt
	}
	return nil
}

func valueBookingCurve(p unsafe.Pointer, c int32) any {
	r := (*demandforecast.BookingCurve)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		if r.CustomerID == "" {
			return nil
		}
		return string(r.CustomerID)
	case 4:
		if r.Shares == nil {
			return keel.EmptyJSONArray
		}
		return r.Shares
	case 5:
		return r.Loads
	case 6:
		return r.FittedAt
	case 7:
		return r.CreatedAt
	}
	return nil
}

