func ptrQuality(p unsafe.Pointer, c int32) any {
	r := (*demandforecast.Quality)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.Status))
	case 3:
		return &r.HistoryWeeks
	case 4:
		return &r.HistoryLoads
	case 5:
		return &r.WeeksTested
	case 6:
		return &r.LoadsTested
	case 7:
		return &r.IntervalCoverage
	case 8:
		return &r.MAE
	case 9:
		return &r.NaiveMAE
	case 10:
		return &r.Skill
	case 11:
		return &r.FittedAt
	case 12:
		return &r.Version
	case 13:
		return &r.CreatedAt
	case 14:
		return &r.UpdatedAt
	}
	return nil
}

func valueQuality(p unsafe.Pointer, c int32) any {
	r := (*demandforecast.Quality)(p)
	switch c {
	case 0:
		return string(r.BusinessUnitID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.Status)
	case 3:
		return r.HistoryWeeks
	case 4:
		return r.HistoryLoads
	case 5:
		return r.WeeksTested
	case 6:
		return r.LoadsTested
	case 7:
		return r.IntervalCoverage
	case 8:
		return r.MAE
	case 9:
		return r.NaiveMAE
	case 10:
		return r.Skill
	case 11:
		return r.FittedAt
	case 12:
		return r.Version
	case 13:
		return r.CreatedAt
	case 14:
		return r.UpdatedAt
	}
	return nil
}

