func newRate() unsafe.Pointer { return unsafe.Pointer(new(demandforecast.Rate)) }

func newNRate(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]demandforecast.Rate, n)))
}

func ptrRate(p unsafe.Pointer, c int32) any {
	r := (*demandforecast.Rate)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 4:
		return &r.Cell
	case 5:
		return &r.Slot
	case 6:
		return &r.Alpha
	case 7:
		return &r.Beta
	case 8:
		return &r.Loads
	case 9:
		return &r.Recent
	case 10:
		return &r.FittedAt
	case 11:
		return &r.CreatedAt
	}
	return nil
}

func valueRate(p unsafe.Pointer, c int32) any {
	r := (*demandforecast.Rate)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		if r.CustomerID == "" {
			return nil
		}
		return string(r.CustomerID)
	case 4:
		return r.Cell
	case 5:
		return r.Slot
	case 6:
		return r.Alpha
	case 7:
		return r.Beta
	case 8:
		return r.Loads
	case 9:
		if r.Recent == nil {
			return keel.EmptyJSONArray
		}
		return r.Recent
	case 10:
		return r.FittedAt
	case 11:
		return r.CreatedAt
	}
	return nil
}

